  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Startup Costs and Funding$j$, $j${"readings": [{"title": "Luke 14 (King James Version)", "url": "/portal/bible/Luke/14"}], "body": "Before you begin a business, count the cost. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Careful planning prevents painful surprises.\n\nStartup costs are the one time expenses needed to open a business, such as equipment, supplies, a website, permits, insurance and your first inventory. Operating costs are the ongoing expenses, such as rent, utilities, advertising and wages. List every expense, add a cushion for the unexpected, and decide how much money you need before the first sale.\n\nFunding can come from several sources. Personal savings is the safest, because it creates no debt. Family and friends may help, but every loan or gift should be written down and understood by both sides. Bank loans and credit require repayment with interest and a good credit history, which most students do not yet have. Grants are money given for a purpose and not repaid, and they often require applications and reporting. Crowdfunding collects small amounts from many people. Investors give money in exchange for part ownership.\n\nWise owners avoid debt that they cannot repay. Proverbs 22:7 says, the borrower is servant to the lender. Never borrow for a business without a clear repayment plan, never sign anything without an adult, and be careful of offers that sound too good to be true. Start small, test the idea and grow with the profits.\n\nYour task: (1) Define startup costs and operating costs. (2) List ten startup costs for your idea with estimated amounts. (3) Explain which funding source is wisest for a beginner.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nNow watch this. Startup costs are one time expenses to open, like equipment, supplies, a website, permits and first inventory. Operating costs are ongoing, like rent, utilities and advertising. List every expense and add a cushion.\n\nFunding sources are personal savings, family and friends, bank loans, grants, crowdfunding and investors. Savings create no debt. Any loan should be written down.\n\nProverbs 22:7 says the borrower is servant to the lender. Never borrow without a repayment plan, never sign anything without an adult and beware offers that sound too good to be true. Start small and grow with the profits.\n\nYour task is to define two terms, list ten startup costs and choose a wise funding source. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Startup Costs and Funding$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Revenue, Expenses, Profit and Budgets$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. A business owner must know the state of the money. This means understanding revenue, expenses, profit and a budget.\n\nRevenue is the money received from sales. Expenses are the costs of running the business. Profit equals revenue minus expenses. If you earn 500 dollars in revenue and spend 350 dollars, the profit is 150 dollars. If expenses are larger than revenue, the result is a loss. Gross profit is revenue minus the direct cost of goods sold. Net profit is what remains after all expenses, including overhead and taxes.\n\nA budget is a plan for how money will be earned and spent. A simple monthly budget lists expected revenue and each expense, then compares the plan to what actually happens. A good budget includes savings for growth, a reserve for emergencies and money set aside for taxes. A common practice is to separate business money from personal money, using a separate account opened with a parent or guardian. Mixing the two makes records confusing and may cause legal and tax problems.\n\nAn income statement, also called a profit and loss statement, summarizes revenue and expenses over a period. A balance sheet shows what a business owns, called assets, what it owes, called liabilities, and what is left for the owner, called equity.\n\nYour task: (1) Define revenue, expense, profit and loss. (2) A business earns 800 dollars and spends 560 dollars. Find the profit. (3) Create a one month budget for your idea.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. An owner must know the state of the money.\n\nNow watch this. Revenue is money received from sales. Expenses are the costs of running the business. Profit equals revenue minus expenses. If revenue is 500 dollars and expenses are 350 dollars, profit is 150 dollars. If expenses are larger, you have a loss.\n\nA budget is a plan for earning and spending. Include savings, an emergency reserve and money set aside for taxes. Keep business money separate from personal money, using an account opened with a parent or guardian.\n\nAn income statement summarizes revenue and expenses. A balance sheet shows assets, liabilities and equity.\n\nYour task is to define four terms, find a profit and create a budget. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Revenue, Expenses, Profit and Budgets$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Break Even Analysis and Cash Flow$j$, $j${"readings": [{"title": "Proverbs 21 (King James Version)", "url": "/portal/bible/Proverbs/21"}], "body": "A business must know how much it needs to sell to cover its costs. The break even point is the level of sales where revenue equals total costs, so profit is zero. Selling more than the break even point creates profit. Proverbs 21:5 says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want.\n\nThe break even formula in units is fixed costs divided by the contribution margin per unit. The contribution margin per unit is the selling price minus the variable cost per unit. Example: a student sells handmade candles for 10 dollars each. Each candle costs 4 dollars in materials. Fixed costs for the month are 600 dollars. The contribution margin is 10 minus 4, which is 6 dollars. The break even point is 600 divided by 6, which is 100 candles. Selling 100 candles covers all costs. Selling 150 candles gives a profit of 50 times 6, which is 300 dollars.\n\nCash flow is the movement of money in and out of the business over time. A business can show a profit on paper and still run out of cash if customers pay late or if inventory is bought before it sells. A cash flow plan lists expected cash in and cash out each week or month. Keep a small cash reserve, bill promptly, collect payments on time and avoid buying more than you can sell.\n\nBreak even and cash flow help you decide whether an idea is realistic before you spend money.\n\nYour task: (1) Define break even point and contribution margin. (2) A business has fixed costs of 400 dollars, a price of 8 dollars and a variable cost of 3 dollars. Find the break even units. (3) Explain why cash flow matters.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 21:5 says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want.\n\nNow watch this. The break even point is where revenue equals total costs, so profit is zero. The formula is fixed costs divided by the contribution margin per unit. The contribution margin is price minus variable cost.\n\nExample. Candles sell for 10 dollars and cost 4 dollars to make, so the margin is 6 dollars. Fixed costs are 600 dollars. Break even is 600 divided by 6, which is 100 candles. Selling 150 candles gives 50 extra candles times 6 dollars, or 300 dollars of profit.\n\nCash flow is the movement of money in and out. A business can be profitable on paper and still run out of cash. Keep a reserve, bill promptly and avoid buying more than you can sell.\n\nYour task is to define two terms, compute a break even point and explain cash flow. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Break Even Analysis and Cash Flow$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Records, Taxes and Honest Reporting$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "Romans 13:7 says, Render therefore to all their dues: tribute to whom tribute is due; custom to whom custom; fear to whom fear; honour to whom honour. Paying taxes honestly and on time is part of good citizenship. This lesson is general education and not tax or legal advice. A real business owner should consult a licensed tax professional or the Internal Revenue Service.\n\nGood records are the foundation of honest business. Keep a record of every sale and every expense, and keep receipts, invoices, bank statements and mileage logs. Record the date, amount, who and what. Use a spreadsheet or accounting software, and back up your records. The IRS generally expects business records to be kept for several years, so ask a professional how long to keep each type.\n\nBusinesses may owe several kinds of taxes. Income tax is owed on net profit. Self employment tax funds Social Security and Medicare for people who work for themselves. Sales tax is collected from customers on taxable sales and sent to the state; Florida businesses that sell taxable items generally register with the Florida Department of Revenue. Employers withhold payroll taxes from employees and send them in on schedule. Some local governments require a business tax receipt. Nonprofits may be exempt from some taxes but still have reporting duties.\n\nNever hide income, claim fake expenses, or pay workers off the books. Tax fraud is a crime. Set aside a part of every sale for taxes, file on time and ask for help when a rule is unclear. Honest records protect you.\n\nYour task: (1) List five records every business should keep. (2) Name three kinds of taxes a business may owe. (3) Explain Romans 13:7 in your own words.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Romans 13:7 says, Render therefore to all their dues: tribute to whom tribute is due. Paying taxes honestly is part of good citizenship. This lesson is general education, not tax advice. A real owner should consult a licensed tax professional.\n\nNow watch this. Good records are the foundation of honest business. Record every sale and every expense. Keep receipts, invoices, bank statements and mileage logs. Use a spreadsheet or software and back it up.\n\nBusinesses may owe income tax, self employment tax, sales tax and payroll taxes. Florida businesses selling taxable items generally register with the Florida Department of Revenue. Some places require a business tax receipt.\n\nNever hide income, claim fake expenses or pay workers off the books. Set aside part of every sale for taxes and file on time.\n\nYour task is to list five records, name three taxes and explain Romans 13:7. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Records, Taxes and Honest Reporting$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Startup Money, Budgets, Break Even and Records$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nPart 1: Define startup costs and operating costs, list ten startup costs for a business idea and explain the safest funding source for a beginner.\nPart 2: Define revenue, expense, profit, loss, asset and liability. A business earns 1200 dollars and spends 850 dollars. Find the profit. Create a one month budget.\nPart 3: Find the break even point for a business with fixed costs of 500 dollars, a price of 9 dollars and a variable cost of 4 dollars. Show your work and explain what happens after break even.\nPart 4: Explain why cash flow matters, list five records to keep and name three taxes a business may owe. Note that this is general education and not tax advice.\nPart 5: Explain how Luke 14:28, Proverbs 22:7 and Romans 13:7 guide a business owner.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Startup Money, Budgets, Break Even and Records$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Counting the Cost$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes an idea you have thought about starting and what you would need to count before you begin, (2) explains why avoiding debt that you cannot repay is wise, (3) explains why honest records and taxes honor God and protect the owner, and (4) connects your answer to Luke 14:28, Proverbs 27:23 or Romans 13:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How much risk is wise for a beginner? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Counting the Cost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Startup Costs and Funding$j$, $j${"questions": [{"q": "Startup costs are:", "options": ["Monthly utilities only", "One time expenses to open a business", "Taxes", "Profits"]}, {"q": "A grant is money that is:", "options": ["Always a loan", "Charged interest", "Given for a purpose and not repaid", "Required to be returned"]}, {"q": "Proverbs 22:7 warns that the borrower is:", "options": ["Rich", "The owner", "Servant to the lender", "Free"]}, {"q": "The safest beginner funding is usually:", "options": ["A stranger's offer", "Unwritten promises", "Personal savings", "A large risky loan"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Startup Costs and Funding$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,2}'::int[], array[$j$Startup costs are paid to get started.$j$,$j$Grants are not repaid.$j$,$j$Debt creates obligation.$j$,$j$Savings carry no repayment debt.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Startup Costs and Funding$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Revenue, Expenses, Profit and Budgets$j$, $j${"questions": [{"q": "Profit equals:", "options": ["Revenue plus expenses", "Price times units", "Revenue minus expenses", "Expenses minus revenue"]}, {"q": "Revenue of 800 dollars and expenses of 560 dollars give a profit of:", "options": ["1360 dollars", "800 dollars", "560 dollars", "240 dollars"]}, {"q": "If expenses exceed revenue the result is a:", "options": ["Grant", "Profit", "Dividend", "Loss"]}, {"q": "Assets are:", "options": ["Its taxes", "What a business owns", "What it owes", "Its logo"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Revenue, Expenses, Profit and Budgets$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,1}'::int[], array[$j$Profit is what remains.$j$,$j$800 minus 560 is 240.$j$,$j$Expenses above revenue are a loss.$j$,$j$Liabilities are what it owes.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Revenue, Expenses, Profit and Budgets$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Break Even Analysis and Cash Flow$j$, $j${"questions": [{"q": "At the break even point, profit is:", "options": ["Unknown", "Negative always", "Maximum", "Zero"]}, {"q": "Fixed costs 600 dollars, price 10 dollars, variable cost 4 dollars. Break even units are:", "options": ["150", "60", "600", "100"]}, {"q": "Contribution margin per unit equals:", "options": ["Price minus variable cost", "Revenue times two", "Fixed cost minus price", "Price plus variable cost"]}, {"q": "Cash flow is:", "options": ["The owner's salary only", "The brand name", "The movement of money in and out over time", "A type of tax"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Break Even Analysis and Cash Flow$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,2}'::int[], array[$j$Revenue equals total costs.$j$,$j$600 divided by 6 is 100.$j$,$j$It is what each unit contributes to fixed costs.$j$,$j$Cash flow tracks timing of money.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Break Even Analysis and Cash Flow$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Records, Taxes and Honest Reporting$j$, $j${"questions": [{"q": "Romans 13:7 teaches us to:", "options": ["Render to all their dues", "Hide income", "Avoid records", "Ignore law"]}, {"q": "Which record should a business keep?", "options": ["Receipts and invoices", "Only slogans", "Nothing", "Only photos"]}, {"q": "Sales tax is collected from:", "options": ["The school", "Banks only", "Customers on taxable sales", "Employees only"]}, {"q": "Paying workers off the books is:", "options": ["A discount", "Required", "Always allowed", "Wrong and illegal"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Records, Taxes and Honest Reporting$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,3}'::int[], array[$j$Honest payment of taxes is part of citizenship.$j$,$j$Records support honest reporting.$j$,$j$The business collects and sends it to the state.$j$,$j$Employers must follow wage and tax laws.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Records, Taxes and Honest Reporting$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Startup Money, Budgets, Break Even and Records$j$, $j${"questions": [{"q": "Counting the cost before building is taught in:", "options": ["Genesis 1:1", "Luke 14:28", "Acts 2:1", "Psalm 1:1"]}, {"q": "Operating costs are:", "options": ["Profits", "Ongoing expenses", "One time purchases only", "Gifts"]}, {"q": "Net profit is what remains after:", "options": ["All expenses", "Nothing", "Only advertising", "Only materials"]}, {"q": "Revenue 500 and expenses 650 results in a:", "options": ["Profit", "Loss", "Gain", "Grant"]}, {"q": "Fixed costs 300, price 7, variable cost 2. Break even units are:", "options": ["30", "100", "60", "150"]}, {"q": "A profitable business can still fail from poor:", "options": ["Color", "Cash flow", "Name", "Weather"]}, {"q": "Keeping business and personal money separate helps:", "options": ["Avoid taxes", "Records stay clear", "Hide income", "Raise prices"]}, {"q": "Tax fraud is:", "options": ["A discount", "A crime", "A strategy", "Optional"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Startup Money, Budgets, Break Even and Records$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,1,2,1,1,1}'::int[], array[$j$Luke 14:28 uses the tower illustration.$j$,$j$Rent and utilities are examples.$j$,$j$Net profit subtracts all expenses.$j$,$j$Expenses exceed revenue.$j$,$j$Margin is 5 and 300 divided by 5 is 60.$j$,$j$Cash timing can break a business.$j$,$j$Separate accounts keep records clean.$j$,$j$Hiding income or faking expenses is illegal.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Startup Money, Budgets, Break Even and Records$j$ on conflict (item_id) do nothing;
